type MediaProps = {
  name: string;
  alt: string;
  width: number;
  height: number;
  sizes?: string;
  priority?: boolean;
  className?: string;
  imgClassName?: string;
  ratio?: string;
};

/**
 * Pre-sized webp sets (640/960/1440) generated by scripts/images.mjs, with
 * intrinsic dimensions so the layout never shifts and a solid ground colour
 * behind the image while it loads.
 */
export function Media({
  name,
  alt,
  width,
  height,
  sizes = "100vw",
  priority = false,
  className = "",
  imgClassName = "",
  ratio,
}: MediaProps) {
  const srcSet = [640, 960, 1440]
    .filter((w) => w <= width * 1.5)
    .map((w) => `/images/${name}-${w}w.webp ${w}w`)
    .join(", ");

  return (
    <span
      className={`media ${className}`}
      style={{ aspectRatio: ratio ?? `${width} / ${height}` }}
    >
      <img
        className={imgClassName}
        src={`/images/${name}-960w.webp`}
        srcSet={srcSet}
        sizes={sizes}
        width={width}
        height={height}
        alt={alt}
        loading={priority ? "eager" : "lazy"}
        fetchPriority={priority ? "high" : "auto"}
        decoding={priority ? "sync" : "async"}
      />
    </span>
  );
}
